for name, data in (("en", EN), ("pl", {**EN, **PL})):
    (root / f"{name}.json").write_text(
        json.dumps({f"SKETCHREVEAL.{k}": v for k, v in data.items()}, ensure_ascii=False, indent=2), encoding="utf-8")
print("ok")
